import com.sun.net.httpserver.*; import java.io.*; import java.net.*; import java.nio.file.*; import java.nio.charset.StandardCharsets; import java.util.*;
public class Main {
 static List<String[]> data=new ArrayList<>(); static Path file=Paths.get("data/students.csv");
 public static void main(String[] a)throws Exception{Files.createDirectories(Paths.get("public"));Files.createDirectories(file.getParent());if(Files.exists(file))for(String l:Files.readAllLines(file)){String[] p=l.split(",",4);if(p.length==4)data.add(p);} HttpServer s=HttpServer.create(new InetSocketAddress(8081),0);s.createContext("/api/students",Main::api);s.createContext("/",Main::web);s.start();System.out.println("Open http://localhost:8081");}
 static void api(HttpExchange e)throws IOException{String m=e.getRequestMethod();if(m.equals("GET")){StringJoiner j=new StringJoiner(",","[","]");for(String[] x:data)j.add(obj(x));send(e,200,j.toString(),"application/json");return;}Map<String,String> p=form(e);if(m.equals("POST")){String id=p.getOrDefault("id","").trim(),name=p.getOrDefault("name","").trim(),marks=p.getOrDefault("marks","").trim();try{String[] nums=marks.split(",");double sum=0,hi=0,lo=100;for(String n:nums){double v=Double.parseDouble(n.trim());if(v<0||v>100)throw new Exception();sum+=v;hi=Math.max(hi,v);lo=Math.min(lo,v);}if(id.isEmpty()||name.isEmpty())throw new Exception();for(String[] x:data)if(x[0].equalsIgnoreCase(id))throw new IllegalStateException();data.add(new String[]{id,name,marks,String.valueOf(sum/nums.length)});save();send(e,201,"{\"message\":\"Student added\"}","application/json");}catch(IllegalStateException ex){send(e,409,"{\"error\":\"Student ID already exists\"}","application/json");}catch(Exception ex){send(e,400,"{\"error\":\"Enter valid marks from 0 to 100, separated by commas\"}","application/json");}return;}if(m.equals("DELETE")){boolean ok=data.removeIf(x->x[0].equals(p.get("id")));save();send(e,ok?200:404,ok?"{}":"{\"error\":\"Not found\"}","application/json");return;}send(e,405,"{}","application/json");}
 static String obj(String[] x){double[] a=Arrays.stream(x[2].split(",")).mapToDouble(v->Double.parseDouble(v.trim())).toArray();double avg=Arrays.stream(a).average().orElse(0),hi=Arrays.stream(a).max().orElse(0),lo=Arrays.stream(a).min().orElse(0);String g=avg>=90?"A+":avg>=80?"A":avg>=70?"B":avg>=60?"C":avg>=50?"D":"F";boolean pass=Arrays.stream(a).allMatch(v->v>=33);return "{\"id\":\""+esc(x[0])+"\",\"name\":\""+esc(x[1])+"\",\"average\":"+Math.round(avg*100)/100.0+",\"highest\":"+hi+",\"lowest\":"+lo+",\"grade\":\""+g+"\",\"result\":\""+(pass?"Pass":"Fail")+"\"}";}
 static void save(){try{List<String> l=new ArrayList<>();for(String[] x:data)l.add(String.join(",",x));Files.write(file,l);}catch(Exception e){}}
 static Map<String,String> form(HttpExchange e)throws IOException{Map<String,String> m=new HashMap<>();for(String x:new String(e.getRequestBody().readAllBytes(),StandardCharsets.UTF_8).split("&")){String[] p=x.split("=",2);if(p.length==2)m.put(URLDecoder.decode(p[0],"UTF-8"),URLDecoder.decode(p[1],"UTF-8"));}return m;}
 static void web(HttpExchange e)throws IOException{String p=e.getRequestURI().getPath();if(p.equals("/"))p="/index.html";Path f=Paths.get("public").resolve(p.substring(1)).normalize();if(!f.startsWith(Paths.get("public"))||!Files.exists(f)){send(e,404,"Not found","text/plain");return;}String t=p.endsWith(".css")?"text/css":p.endsWith(".js")?"application/javascript":"text/html";send(e,200,Files.readString(f),t);}
 static String esc(String s){return s.replace("\\","\\\\").replace("\"","\\\"");}
 static void send(HttpExchange e,int c,String b,String t)throws IOException{byte[] z=b.getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type",t+"; charset=utf-8");e.sendResponseHeaders(c,z.length);e.getResponseBody().write(z);e.close();}
}
